D.every=[{"k": "tashahhud", "t": "At-Tahiyyat (Tashahhud)", "bnt": "আত্তাহিয়্যাতু", "n": "Sit and read", "when": "In the sitting after the 2nd rakat, and again in the final sitting of every prayer of 2, 3 or 4 rakats. Raise the index finger at “la ilaha” and lower it at “illallah” (Hanafi practice).", "ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "p": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়্যিবাত। আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ। আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহীন। আশহাদু আল লা ইলাহা ইল্লাল্লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু।", "b": "সব সম্মান, সব নামায ও সব পবিত্র কথা আল্লাহর জন্য। হে নবী, আপনার উপর শান্তি এবং আল্লাহর রহমত ও বরকত বর্ষিত হোক। আমাদের উপর এবং আল্লাহর সৎ বান্দাদের উপর শান্তি বর্ষিত হোক। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মদ ﷺ তাঁর বান্দা ও রাসূল।", "e": "All greetings, prayers and good words are for Allah. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon Allah’s righteous servants. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger."}, {"k": "durood", "t": "Durood Ibrahim", "bnt": "দরূদে ইবরাহীম", "n": "Sit and read", "when": "In the final sitting only, straight after Tashahhud (in fard, and in the last sitting of sunnah and nafl). Not read in the first sitting of a 3 or 4 rakat fard prayer.", "ar": "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ", "p": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ।", "b": "হে আল্লাহ, মুহাম্মদ ﷺ ও তাঁর পরিবারের উপর রহমত বর্ষণ করুন, যেমন আপনি ইবরাহীম (আ.) ও তাঁর পরিবারের উপর রহমত বর্ষণ করেছেন। নিশ্চয়ই আপনি প্রশংসিত ও মহিমান্বিত। হে আল্লাহ, মুহাম্মদ ﷺ ও তাঁর পরিবারকে বরকত দিন, যেমন আপনি ইবরাহীম (আ.) ও তাঁর পরিবারকে বরকত দিয়েছেন। নিশ্চয়ই আপনি প্রশংসিত ও মহিমান্বিত।", "e": "O Allah, send mercy upon Muhammad and the family of Muhammad, as You sent mercy upon Ibrahim and the family of Ibrahim. You are Praiseworthy and Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim. You are Praiseworthy and Glorious."}, {"k": "dua1", "t": "Dua after Durood: Rabbana Atina", "bnt": "দোয়া মাসূরা ১", "n": "Sit and read", "when": "In the final sitting, after Durood and before the Salam. Choose one dua, or read more than one.", "ar": "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "p": "রাব্বানা আতিনা ফিদ দুনিয়া হাসানাতাঁও ওয়া ফিল আখিরাতি হাসানাতাঁও ওয়া কিনা আযাবান নার।", "b": "হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতেও কল্যাণ দিন এবং আমাদের জাহান্নামের আযাব থেকে রক্ষা করুন। (সূরা বাকারা ২:২০১)", "e": "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire. (Al-Baqarah 2:201)"}, {"k": "dua2", "t": "Dua after Durood: Rabbij’alni", "bnt": "দোয়া মাসূরা ২", "n": "Sit and read", "when": "In the final sitting, after Durood and before the Salam.", "ar": "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ، رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", "p": "রাব্বিজ’আলনী মুকীমাস সালাতি ওয়া মিন যুররিয়্যাতী, রাব্বানা ওয়া তাকাব্বাল দু’আ। রাব্বানাগফির লী ওয়া লি ওয়ালিদাইয়্যা ওয়া লিল মু’মিনীনা ইয়াওমা ইয়াকূমুল হিসাব।", "b": "হে আমার রব, আমাকে নামায কায়েমকারী বানান এবং আমার বংশধরদেরও। হে আমাদের রব, আমার দোয়া কবুল করুন। হে আমাদের রব, হিসাবের দিনে আমাকে, আমার পিতা-মাতাকে ও সব মুমিনকে ক্ষমা করুন। (সূরা ইবরাহীম ১৪:৪০-৪১)", "e": "My Lord, make me an establisher of prayer, and my descendants too. Our Lord, accept my prayer. Our Lord, forgive me, my parents and the believers on the Day the reckoning is established. (Ibrahim 14:40-41)"}, {"k": "dua3", "t": "Dua after Durood: Allahumma inni zalamtu", "bnt": "দোয়া মাসূরা ৩", "n": "Sit and read", "when": "In the final sitting, after Durood and before the Salam. Abu Bakr (may Allah be pleased with him) asked the Prophet ﷺ for a dua to read in prayer, and he taught this (Bukhari, Muslim).", "ar": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "p": "আল্লাহুম্মা ইন্নী যালামতু নাফসী যুলমান কাসীরা, ওয়া লা ইয়াগফিরুয যুনূবা ইল্লা আনতা, ফাগফির লী মাগফিরাতাম মিন ইনদিকা ওয়ারহামনী, ইন্নাকা আনতাল গাফূরুর রাহীম।", "b": "হে আল্লাহ, আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে ক্ষমা করুন এবং আমার উপর দয়া করুন। নিশ্চয়ই আপনি ক্ষমাশীল, পরম দয়ালু।", "e": "O Allah, I have wronged myself greatly, and none forgives sins except You. So grant me forgiveness from You and have mercy on me. You are the Forgiving, the Merciful."}, {"k": "salam", "t": "Salam: ending the prayer", "bnt": "সালাম", "n": "Turn and say", "when": "Last step of every prayer: turn the face to the right shoulder and say it, then turn to the left shoulder and say it again.", "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "p": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "b": "আপনাদের উপর শান্তি এবং আল্লাহর রহমত বর্ষিত হোক।", "e": "Peace and the mercy of Allah be upon you."}];
