const GUIDE=[
{ic:'💧',t:'How to make Wudu (ablution)',b:`<p>Wudu makes you clean and ready to stand before Allah. Do each step in this order.</p>
<ol class="steps"><li>Make the niyyah in your heart and say <b>Bismillah</b>.</li><li>Wash both hands up to the wrists, <b>3 times</b>.</li><li>Rinse the mouth <b>3 times</b>.</li><li>Sniff water into the nose and blow it out, <b>3 times</b>.</li><li>Wash the whole face, <b>3 times</b> (from hairline to chin, ear to ear).</li><li>Wash the right arm up to and including the elbow, then the left, <b>3 times</b> each.</li><li>Wipe over the head with wet hands, <b>once</b> (then the ears).</li><li>Wash the right foot up to and including the ankle, then the left, <b>3 times</b> each.</li></ol>
<div class="arline">أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ</div>
<p class="bn" style="text-align:center;font-weight:700;color:var(--brand)">আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু</p>
<div class="callout"><b>Fard (must-do) parts in Hanafi fiqh:</b> wash the face, wash both arms to the elbows, wipe at least a quarter of the head, wash both feet to the ankles. Everything else is sunnah or mustahab. Do not waste water.</div>`},
{ic:'🚫',t:'What breaks Wudu (and when to redo it)',b:`<div class="split"><div><h3 class="x">Breaks wudu</h3><ul class="bul"><li>Anything that leaves the private parts: urine, stool, gas, or other discharge.</li><li>Blood or pus that flows out of the body.</li><li>Vomiting a mouthful.</li><li>Sleeping lying down, leaning, or any deep sleep that loses control.</li><li>Fainting, madness or intoxication.</li><li>Laughing out loud during a prayer that has ruku and sajdah (Hanafi).</li></ul></div><div><h3 class="ok">Does not break wudu (Hanafi)</h3><ul class="bul"><li>Doubt only: if you are unsure, keep your wudu.</li><li>A tiny drop of blood that does not flow.</li><li>Touching the private part or touching your spouse.</li><li>Eating any food, or a short nap while sitting upright.</li></ul></div></div><div class="callout">If wudu breaks, stop, make wudu again, and continue. Each fard prayer needs a valid wudu.</div>`},
{ic:'🧍',t:'How to stand (Qiyam)',b:`<ul class="bul"><li>Face the <b>Qiblah</b>, stand straight, feet about four fingers apart and pointing forward.</li><li>Look at the spot where your forehead will touch the ground.</li><li>After the takbir, men fold hands <b>below the navel</b>, right over left; women fold hands on the chest.</li><li>Stay calm and still. Do not rock or fidget.</li></ul>`},
{ic:'🙇',t:'How to do Ruku (bowing)',b:`<ol class="steps"><li>Say <b>“Allahu Akbar”</b> and bow.</li><li>Hands on the knees, fingers spread, back flat and straight, head level with the back.</li><li>Say <b>“Subhana Rabbiyal Azeem”</b> at least 3 times, calmly.</li><li>Rise saying <b>“Sami’Allahu liman hamidah”</b>, then <b>“Rabbana lakal hamd”</b>. Stand fully straight.</li></ol><div class="callout">Pause in every position until each bone rests. This calm stop is called <b>tuma’ninah</b> and prayer is not complete without it.</div>`},
{ic:'🤲',t:'How to do Sajdah (prostration)',b:`<ol class="steps"><li>Say <b>“Allahu Akbar”</b> and go down: knees, then hands, then nose and forehead.</li><li>Seven parts touch the ground: <b>forehead with nose, both palms, both knees, toes of both feet</b>.</li><li>Face between the hands, fingers together and pointing to the Qiblah.</li><li>Say <b>“Subhana Rabbiyal A’la”</b> at least 3 times. This is the best place to make dua.</li><li>Sit up saying “Allahu Akbar”, rest a moment, then do the second sajdah.</li></ol><div class="split"><div class="callout"><b>Men:</b> lift the elbows away from the ground and the tummy away from the thighs.</div><div class="callout"><b>Women:</b> keep the body close and compact, elbows against the sides.</div></div>`},
{ic:'👕',t:'Dress code (Awrah) and clean place',b:`<ul class="bul"><li><b>Boys and men:</b> cover at least from the navel to below the knees. A cap or head covering is recommended.</li><li><b>Girls and women:</b> cover the whole body except the face, hands and feet. Clothes must not be see-through or tight.</li><li>Clothes, body and prayer place must be <b>clean (pak)</b>.</li><li>Wear neat, comfortable clothes. Avoid pictures or writing that distracts.</li><li>Face the Qiblah. Use a clean prayer mat or clean floor.</li></ul>`},
{ic:'📋',t:'Essentials of Salah (conditions and pillars)',b:`<div class="split"><div><h3>Before the prayer (conditions)</h3><ul class="bul"><li>Body clean from hadath (wudu or ghusl).</li><li>Body, clothes and place clean from najasah.</li><li>Awrah covered.</li><li>Facing the Qiblah.</li><li>Prayer time has come in.</li><li>Niyyah (intention).</li></ul></div><div><h3>Inside the prayer (fard)</h3><ul class="bul"><li>Takbir Tahrimah: “Allahu Akbar” to begin.</li><li>Qiyam: standing (in fard prayers).</li><li>Qira’ah: reciting at least one verse of the Quran.</li><li>Ruku: bowing.</li><li>Sajdah: two prostrations in every rakat.</li><li>Final sitting long enough for Tashahhud.</li></ul></div></div><p class="note">Wajib parts (like Al-Fatiha and a surah, and Qunoot in Witr) must not be left. If forgotten by mistake, Sajdah Sahw fixes it. Ask your teacher for details.</p>`},
{ic:'⛔',t:'What not to do inside Salah',b:`<ul class="bul"><li>Talking, eating or drinking.</li><li>Laughing, or turning the chest away from the Qiblah.</li><li>Looking around or up to the sky, or playing with clothes, hair or fingers.</li><li>Unnecessary moving; repeated big movements can end the prayer.</li><li>Rushing through positions without tuma’ninah.</li><li>Praying when you badly need the toilet, or when food is served and you are hungry.</li><li>Praying at the forbidden times: sunrise, exact midday (zawal) and sunset.</li><li>Walking in front of someone who is praying (it is a sin).</li></ul>`},
{ic:'🌟',t:'How to earn the highest reward (Khushu)',b:`<ul class="bul"><li>Pray <b>on time</b> and, when you can, <b>in jamaah</b> at the masjid.</li><li>Make wudu well and get to the prayer early.</li><li>Know what you say. Learn the meaning of Al-Fatiha and the short surahs.</li><li>Look at the place of sajdah and remember: <i>“Worship Allah as if you see Him; if you do not see Him, He sees you.”</i> (Bukhari, Muslim)</li><li>Recite slowly. Stay calm in every position.</li><li>Ask Allah in sajdah for what you need.</li><li>Pray the sunnah before and after the fard, and finish with dhikr.</li><li>Pray as if it is your last prayer.</li></ul><p><a class="btn" href="#/dua/after">See dhikr after every Salah →</a></p>`}
];
function star(n){return `<span class="star"><svg viewBox="0 0 44 44"><use href="#star"/></svg><span>${n}</span></span>`}
