function surahList(){setNav('surah');
 const f=store.get('sf','salah'),q=store.get('sq','');
 const ok=D.sur.filter(s=>(f==='all'||s.s)&&(!q||(s.t+' '+s.tr+' '+s.bn+' '+s.n).toLowerCase().includes(q.toLowerCase())));
 const learned=store.get('learned',{});
 app.innerHTML=`<span class="eyebrow">Learn the surahs</span><h1>Surah for Salah</h1>${sub([['#/surah','Surahs to recite'],['#/surah/every','Read in every Salah']],'#/surah')}<p class="lead">These surahs are short enough to recite in prayer. Gold cards open in the reader. Tap one to start.</p>
 <div class="tools"><button class="chip" aria-pressed="${f==='salah'}" data-f="salah">Salah surahs (${D.sur.filter(s=>s.s).length})</button><button class="chip" aria-pressed="${f==='all'}" data-f="all">All 114</button><input class="search" id="q" type="search" placeholder="Search a surah name or number" value="${esc(q)}" aria-label="Search surahs"></div>
 <div class="grid" id="g">${ok.map(s=>{const L=s.s;const inner=`${star(s.n)}<span class="t"><b>${esc(s.t)}</b><small>${esc(s.tr)} · ${s.v} verses${learned[s.n]?' · <span class="done">✓ learned</span>':''}</small></span><span class="a">${s.ar}</span>${L?'<span class="tag">Salah</span>':''}`;return L?`<a class="sc on" href="#/surah/${s.n}">${inner}</a>`:`<div class="sc off" title="Not in the salah set yet">${inner}</div>`}).join('')||'<p>No surah found.</p>'}</div>
 <p class="note">Longer surahs are listed for reference. Their readers can be added next.</p>`;
 app.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{store.set('sf',b.dataset.f);surahList()});
 $('#q').oninput=e=>{store.set('sq',e.target.value);const p=e.target.selectionStart;surahList();const i=$('#q');i.focus();i.setSelectionRange(p,p)}}
function everyView(){setNav('surah');
 const fs=store.get('fs',1);
 app.innerHTML=`<span class="eyebrow">Learn the surahs</span><h1>Surah for Salah</h1>${sub([['#/surah','Surahs to recite'],['#/surah/every','Read in every Salah']],'#/surah/every')}
 <p class="lead">These are not surahs, but you read them in every prayer while sitting: Tashahhud, Durood, a dua, and the Salam. Learn them by heart first.</p>
 <div class="flow" style="margin-top:16px">Sit after 2nd rakat <span>→</span> Tashahhud <span>→</span> final sitting: Tashahhud + Durood + Dua <span>→</span> Salam</div>
 <div class="ctl" style="justify-content:flex-start"><button class="chip" data-z="-1" aria-label="Smaller text">A−</button><button class="chip" data-z="1" aria-label="Larger text">A+</button></div>
 <div class="verses" id="rd" style="--fs:${fs}">${D.every.map((x,i)=>`<article class="v" style="grid-template-columns:1fr"><div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span class="vn">${i+1}</span><h3 style="font-size:1.25rem">${esc(x.t)}</h3><span class="tag" style="position:static;margin-left:auto">${esc(x.n)}</span></div><div class="ar" lang="ar" style="margin-top:8px">${x.ar}</div><div class="pr">${esc(x.p)}</div><div class="bt">${esc(x.b)}</div><div class="et">${esc(x.e)}</div><div class="wh" style="margin-top:12px;padding:8px 14px;border-radius:12px;background:var(--goldsoft);border:1.5px dashed var(--gold);font-weight:700;font-size:.93rem"><b style="color:var(--gold);text-transform:uppercase;letter-spacing:.06em;font-size:.78rem">When:</b> ${esc(x.when)}</div></div></article>`).join('')}</div>
 <div class="tipbox">Prayer of 2 rakats: Tashahhud, Durood, Dua, Salam in the last sitting. Prayer of 3 or 4 rakats: only Tashahhud in the first sitting (after the 2nd rakat), then the full set in the last.</div>`;
 app.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{const z=Math.min(1.6,Math.max(.8,+(store.get('fs',1)+.1*b.dataset.z).toFixed(2)));store.set('fs',z);$('#rd').style.setProperty('--fs',z)})}
function reader(n){setNav('surah');
 const s=D.sur.find(x=>x.n==n);if(!s||!s.s){go('/surah');return}
 const idx=D.sur.filter(x=>x.s),i=idx.indexOf(s),prev=idx[i-1],next=idx[i+1];
 const lay=store.get('lay',{ar:1,pr:1,bn:1,en:1}),fs=store.get('fs',1),learned=store.get('learned',{});
 const bis=n!=1?`<div class="bismbox"><div class="ar">بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</div><div class="pr">বিসমিল্লাহির রাহমানির রাহীম</div></div>`:'';
 app.innerHTML=`<a class="crumb" href="#/surah">← All surahs</a><section class="rhead"><div class="a">${s.ar}</div><div class="bnn">${esc(s.bn)}</div><h2>${esc(s.t)} · ${esc(s.tr)}</h2><div class="meta">Surah ${s.n} · ${s.v} verses · ${esc(s.ty)}</div></section>
 <div class="ctl"><button class="chip" aria-pressed="${!!lay.ar}" data-l="ar">Arabic</button><button class="chip" aria-pressed="${!!lay.pr}" data-l="pr">Pronunciation</button><button class="chip" aria-pressed="${!!lay.bn}" data-l="bn">বাংলা</button><button class="chip" aria-pressed="${!!lay.en}" data-l="en">English</button><button class="chip" data-z="-1" aria-label="Smaller text">A−</button><button class="chip" data-z="1" aria-label="Larger text">A+</button></div>
 <div id="rd" class="${['ar','pr','bn','en'].filter(k=>!lay[k]).map(k=>'hide-'+k).join(' ')}" style="--fs:${fs}">${bis}<div class="verses">${s.verses.map((v,j)=>`<article class="v"><div class="vn">${j+1}</div><div><div class="ar" lang="ar">${v.a}</div><div class="pr">${esc(v.p)}</div><div class="bt">${esc(v.b)}</div><div class="et">${esc(v.e)}</div></div></article>`).join('')}</div></div>
 <div class="tipbox">${s.n==1?'Recite Al-Fatiha in every rakat of every prayer.':'Recite after Al-Fatiha in the 1st and 2nd rakat of fard prayers, and in every rakat of sunnah and nafl.'}</div>
 <div class="pager">${prev?`<a class="btn ghost" href="#/surah/${prev.n}">← ${esc(prev.t)}</a>`:'<span></span>'}<button class="btn ${learned[n]?'ghost':''}" id="ln">${learned[n]?'✓ Learned':'I learned this surah'}</button>${next?`<a class="btn ghost" href="#/surah/${next.n}">${esc(next.t)} →</a>`:'<span></span>'}</div>`;
 app.querySelectorAll('[data-l]').forEach(b=>b.onclick=()=>{lay[b.dataset.l]=lay[b.dataset.l]?0:1;store.set('lay',lay);reader(n)});
 app.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{const z=Math.min(1.6,Math.max(.8,+(fs+.1*b.dataset.z).toFixed(2)));store.set('fs',z);$('#rd').style.setProperty('--fs',z);fs2=z});let fs2=fs;
 $('#ln').onclick=()=>{learned[n]=!learned[n];store.set('learned',learned);reader(n)}}
const KIND={fard:'bd fard',sun:'bd sun',sun2:'bd sun2',nafl:'bd nafl',wajib:'bd wajib'};
function salahHome(tab){setNav('salah');
 const cur=`#/salah/${tab}`;
 let body='';
 if(tab==='fard') body=`<p class="lead">The five prayers that every Muslim must pray every day. Tap a prayer to see how to pray it.</p><div class="cards" style="margin-top:18px">${D.fard.map(p=>`<a class="pc" style="--acc:${p.acc}" href="#/salah/fard/${p.key}"><div class="row"><div><h3>${esc(p.en)}</h3><p>${esc(p.sub)}</p></div><div class="a">${p.ar}</div></div><p>${esc(p.time)}</p><div class="badges">${p.blocks.map(b=>`<span class="${KIND[b[3]]}">${b[0]} ${b[1]}</span>`).join('')}</div></a>`).join('')}</div>`;
 else if(tab==='extra') body=`<p class="lead">Extra prayers that bring a lot of reward: Tahajjud, Duha, Awwabin, Witr and more. They include sunnah, nafl and wajib prayers.</p><div class="cards" style="margin-top:18px">${D.extra.map(p=>`<a class="pc" style="--acc:${p.acc}" href="#/salah/extra/${p.key}"><div class="row"><div><h3>${esc(p.en)}</h3><p>${esc(p.sub)}</p></div><div class="a">${p.ar}</div></div><p>${esc(p.time)}</p><div class="badges">${p.blocks.map(b=>`<span class="${KIND[b[3]]||'bd nafl'}">${b[0]} ${b[1]}</span>`).join('')}</div></a>`).join('')}</div>`;
 else body=`<p class="lead">Pictures, animations and colours to help you learn. Tap a section to jump to it.</p>${guideHTML()}`;
 app.innerHTML=`<span class="eyebrow">Learn to pray</span><h1>Salah</h1>${sub([['#/salah/fard','5 Daily Fard Prayers'],['#/salah/extra','Sunnah, Wajib & Nafl'],['#/salah/guide','Wudu & Salah Guide']],cur)}${body}`;if(tab==='guide')guideInit()}
function prayer(grp,key){setNav('salah');
 const L=grp==='fard'?D.fard:D.extra,p=L.find(x=>x.key===key);if(!p){go('/salah');return}
 const isF=grp==='fard';
 const glance=isF?[[p.n,'Rakats'],[p.n,'Ruku'],[p.n*2,'Sajdah'],[p.recit.includes('silent')&&p.recit.includes('Aloud')?'Aloud + silent':p.recit.split(' in ')[0],'Recitation']]:p.glance.map(g=>[g[0],g[1]]);
 const steps=p.steps;
 app.innerHTML=`<a class="crumb" href="#/salah/${grp}">← ${isF?'5 daily prayers':'Other prayers'}</a><section class="dhead" style="--acc:${p.acc}"><div class="a">${p.ar}</div><h1>${esc(p.en)}</h1><div class="meta">${esc(p.sub)} · ${esc(p.time)}</div><div class="rak">${p.blocks.map(b=>`<div class="rk ${b[3]}"><b>${b[0]}</b><small>${esc(b[1])}</small><i>${esc(b[2])}</i></div>`).join('')}</div></section>
 <div class="cols"><div class="box"><h3>How to pray</h3><ol class="steps">${steps.map(s=>`<li><span>${s}</span></li>`).join('')}</ol><p style="margin:16px 0 0"><a class="btn ghost" href="#/surah/every">Read Tashahhud, Durood &amp; Dua →</a></p></div><div style="display:grid;gap:16px;align-content:start"><div class="box"><h3>${isF?'Fard at a glance':'At a glance'}</h3><div class="glance">${glance.map(g=>`<div class="gl"><b>${esc(g[0])}</b><small>${esc(g[1])}</small></div>`).join('')}</div></div><div class="box"><h3>${isF?'This prayer':'In brief'}</h3><p style="margin:0"><b>${isF?esc(p.recit)+'.':''}</b> ${esc(isF?p.rule:p.brief)}</p></div></div></div>
 <div class="two"><div class="box"><h3>${isF?'Wajib':esc(p.t1)}</h3><ul class="bul">${(isF?p.wajib:p.b1).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="box"><h3>${isF?'Nafl &amp; notes':esc(p.t2)}</h3><ul class="bul">${(isF?p.nafl:p.b2).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>
 <div class="tipbox">${esc(p.tip)}</div>
 <div class="pager">${(()=>{const i=L.indexOf(p),a=L[i-1],b=L[i+1];return `${a?`<a class="btn ghost" href="#/salah/${grp}/${a.key}">← ${esc(a.en)}</a>`:'<span></span>'}${isF?`<a class="btn" href="#/dua/after">Dhikr after ${esc(p.en)} →</a>`:'<a class="btn" href="#/dua/dua">Related duas →</a>'}${b?`<a class="btn ghost" href="#/salah/${grp}/${b.key}">${esc(b.en)} →</a>`:'<span></span>'}`})()}</div>`}
function duaView(tab){setNav('dua');
 const cur=`#/dua/${tab}`;
 const list=D.cards.filter(c=>c.grp===tab);
 const card=(c,i)=>`<details class="dc" style="--acc:${c.acc}"${i===0?' open':''} id="c-${c.key}"><summary><span><b>${esc(c.en)}</b><small>${esc(c.bn)}</small></span><span class="a">${c.ar}</span></summary>${c.items.map(it=>`<div class="di">${it.cnt?`<span class="cnt">${esc(it.cnt)}</span>`:''}${it.name?`<div class="eyebrow" style="text-align:center">${esc(it.name)}</div>`:''}<div class="ar" lang="ar">${it.ar}</div><div class="pr">${esc(it.bn)}</div>${it.en?`<div class="et">${esc(it.en)}</div>`:''}${it.wh?`<div class="wh"><b>${tab==='after'?'When':'Best time'}:</b> ${esc(it.wh)}</div>`:''}</div>`).join('')}${c.when?`<div class="di"><div class="wh" style="margin:0"><b>When:</b> ${esc(c.when)}</div></div>`:''}<div class="dtip">${esc(c.tip)}</div></details>`;
 app.innerHTML=`<span class="eyebrow">Every day</span><h1>Dua &amp; Dhikr</h1>${sub([['#/dua/after','Dhikr after Salah'],['#/dua/dua','Duas']],cur)}
 ${tab==='after'?`<div class="flow">Prayer ends <span>→</span> Astaghfirullah ×3 <span>→</span> Tasbih Fatimi ×100 <span>→</span> Ayat al-Kursi <span>→</span> Three Quls</div><p class="lead" style="margin-bottom:18px">Say these after every fard prayer, in this order. Open each one to read it.</p>`:`<p class="lead" style="margin-bottom:18px">Duas for the people and needs in your life. Each one tells you the best time to ask.</p>`}
 ${list.map(card).join('')}`}

const HK=[['َ','Fatḥah','জবর / যবর'],['ِ','Kasrah','জের / যের'],['ُ','Ḍammah','পেশ']];
function forms(x){const z='\u200d',c=x.ar;return x.j?[[c,'Alone'],[c+z,'Start'],[z+c+z,'Middle'],[z+c,'End']]:[[c,'Alone'],[z+c,'End']]}
function toast(m){const d=document.createElement('div');d.className='toast';d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),3200)}
async function getPdf(){
 if(PROD){const a=document.createElement('a');a.href='/downloads/arabic-alphabet-writing-practice.pdf';a.download='arabic-alphabet-writing-practice.pdf';document.body.appendChild(a);a.click();a.remove();track('pdf_download');return}
 if(!DL){toast('Download works when this page is opened inside Claude.');return}
 try{const bin=atob(PDF_B64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
  await DL.save({filename:'arabic-alphabet-writing-practice.pdf',data:new Blob([u],{type:'application/pdf'})});toast('Saved. Print it and start writing!')}
 catch(e){if(e&&e.code==='declined')return;toast('Could not save the file. Please try again.')}}
function alphabet(){setNav('alphabet');
 app.innerHTML=`<span class="eyebrow">Learn to read the Quran</span><h1>Arabic Alphabet</h1><p class="lead">28 letters. Tap a letter to see its name, how to say it in Bangla, and how it sounds with jabar, jer and pesh. Arabic starts from the right, so alif is at the top right.</p>
 <div class="dl"><p>Printable writing practice: every letter on its own line with a solid model, dotted letters to trace, and empty lines to write. 4 pages, A4.</p><button class="btn" id="pdfb">Download writing practice PDF</button></div>
 <div class="agrid">${AL.map((x,i)=>`<button class="al" data-i="${i}" aria-label="${x.en}, letter ${i+1}"><span class="no">${i+1}</span><span class="l" lang="ar">${x.ar}</span><b>${x.en}</b><small>${x.bn}</small></button>`).join('')}</div>
 <p class="note">Sounds are described in Bangla and English. A teacher should help you with the throat letters such as ح ع غ ق.</p>
 <dialog class="md" id="dlg" aria-label="Letter details"></dialog>`;
 $('#pdfb').onclick=getPdf;
 const dlg=$('#dlg');let cur=0;
 function show(i){cur=(i+AL.length)%AL.length;const x=AL[cur];const base=x.ar==='ا'?['أ','إ','أ']:[x.ar,x.ar,x.ar];
  dlg.innerHTML=`<div class="mb"><div class="mtop"><span class="eyebrow">Letter ${cur+1} of 28</span><button class="x" id="cx" aria-label="Close">×</button></div>
  <div class="big" lang="ar">${x.ar}</div><div class="nm2"><h2>${x.en} · <span class="ar">${x.ar==='ا'?'ألف':x.ar}</span></h2><div class="bn">${x.bn}</div></div>
  <div class="snd"><p><b>Sounds like:</b> ${esc(x.se)}</p><p class="bn"><b>বাংলায়:</b> ${esc(x.sb)}</p></div>
  <h4 class="mh">Jabar, Jer, Pesh</h4><div class="hk">${HK.map((h,k)=>`<div><span class="ar" lang="ar">${base[k]}${h[0]}</span><b>${h[1]}</b><span class="bn">${h[2]}</span><small>${esc(x.h[k])} (${x.ro}${['a','i','u'][k]})</small></div>`).join('')}</div>
  <h4 class="mh">How it looks in a word</h4><div class="fm">${forms(x).map(f=>`<div><span class="ar" lang="ar">${f[0]}</span><small>${f[1]}</small></div>`).join('')}</div>
  <div class="mnav"><button class="btn ghost" id="pv">← ${AL[(cur+27)%28].en}</button><button class="btn ghost" id="nx">${AL[(cur+1)%28].en} →</button></div></div>`;
  $('#cx').onclick=()=>dlg.close();$('#pv').onclick=()=>show(cur-1);$('#nx').onclick=()=>show(cur+1)}
 app.querySelectorAll('.al').forEach(b=>b.onclick=()=>{show(+b.dataset.i);dlg.showModal()});
 dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close()});
 dlg.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(cur-1);if(e.key==='ArrowLeft')show(cur+1)})}
const GC={wudu:'#2b86c5',breaks:'#c0392b',stand:'#2f8f5b',ruku:'#d9822b',sajdah:'#7a4fb5',dress:'#0f8a8a',ess:'#b8891f',donts:'#c0392b',khushu:'#a3489b'};
