function mkFig(host,start,seven){
 host.innerHTML=`<svg viewBox="30 40 270 176" role="img" aria-label="Prayer posture"><rect x="20" y="200" width="280" height="14" rx="7" style="fill:color-mix(in srgb,var(--c) 40%,var(--surface))"/>
 <g stroke-linecap="round" fill="none" style="stroke:var(--brand)"><line id="fl" stroke-width="16"/><line id="fs" stroke-width="16"/><line id="ff" stroke-width="9"/><line id="ft" stroke-width="22"/><line id="fa" stroke-width="10" style="stroke:color-mix(in srgb,var(--brand) 70%,#fff)"/><line id="fb" stroke-width="10" style="stroke:color-mix(in srgb,var(--brand) 70%,#fff)"/></g>
 <circle id="fh" r="15" style="fill:var(--surface);stroke:var(--brand);stroke-width:5"/>
 ${seven?'<circle class="gdot" id="d1" r="7"/><circle class="gdot" id="d2" r="7"/><circle class="gdot" id="d3" r="7"/><circle class="gdot" id="d4" r="7"/>':''}</svg>`;
 const q=id=>host.querySelector('#'+id);let cur=JSON.parse(JSON.stringify(POSE[start])),raf=0;
 const red=matchMedia('(prefers-reduced-motion:reduce)').matches;
 function put(p){const L=(e,a,b)=>{e.setAttribute('x1',a[0]);e.setAttribute('y1',a[1]);e.setAttribute('x2',b[0]);e.setAttribute('y2',b[1])};
  L(q('fl'),p.hip,p.kn);L(q('fs'),p.kn,p.ank);L(q('ff'),p.ank,p.toe);L(q('ft'),p.hip,p.sh);L(q('fa'),p.sh,p.el);L(q('fb'),p.el,p.wr);q('fh').setAttribute('cx',p.hd[0]);q('fh').setAttribute('cy',p.hd[1]);
  if(seven){[[p.hd[0]+2,p.hd[1]+14],[p.wr[0],p.wr[1]],[p.kn[0],p.kn[1]+2],[p.toe[0],p.toe[1]+2]].forEach((c,i)=>{const d=q('d'+(i+1));d.setAttribute('cx',c[0]);d.setAttribute('cy',c[1])})}}
 put(cur);
 function set(name,on){const to=POSE[name];cancelAnimationFrame(raf);const from=JSON.parse(JSON.stringify(cur));const t0=performance.now(),D=red?1:900;
  seven&&host.querySelectorAll('.gdot').forEach(d=>d.classList.toggle('on',!!(on&&to.pts)));
  function f(t){const k=Math.min(1,(t-t0)/D),e=k<.5?2*k*k:1-Math.pow(-2*k+2,2)/2;for(const key in to){if(key==='pts')continue;cur[key]=[from[key][0]+(to[key][0]-from[key][0])*e,from[key][1]+(to[key][1]-from[key][1])*e]}put(cur);if(k<1)raf=requestAnimationFrame(f)}raf=requestAnimationFrame(f)}
 return{set}}
const PSEQ=[
{p:'qiyam',t:'1. Qiyam · Standing',ar:'اللَّهُ أَكْبَرُ',bn:'আল্লাহু আকবার',en:'Allah is the Greatest (Takbir), then Thana, Bismillah, Al-Fatiha and a surah.'},
{p:'ruku',t:'2. Ruku · Bowing',ar:'سُبْحَانَ رَبِّيَ الْعَظِيمِ',bn:'সুবহানা রাব্বিয়াল আযীম (৩ বার)',en:'Glory to my Lord, the Mighty. Back flat, hands on knees.'},
{p:'qawmah',t:'3. Qawmah · Rising',ar:'سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ، رَبَّنَا لَكَ الْحَمْدُ',bn:'সামি‘আল্লাহু লিমান হামিদাহ, রাব্বানা লাকাল হামদ',en:'Allah hears the one who praises Him. Our Lord, all praise is Yours. Stand fully straight.'},
{p:'sajdah',t:'4. Sajdah · Prostration',ar:'سُبْحَانَ رَبِّيَ الْأَعْلَىٰ',bn:'সুবহানা রাব্বিয়াল আ‘লা (৩ বার)',en:'Glory to my Lord, the Most High. Seven parts touch the ground.'},
{p:'jalsa',t:'5. Jalsa · Sitting',ar:'رَبِّ اغْفِرْ لِي',bn:'রাব্বিগফির লী',en:'My Lord, forgive me. Sit calmly until still, then go down again.'},
{p:'sajdah',t:'6. Second Sajdah',ar:'سُبْحَانَ رَبِّيَ الْأَعْلَىٰ',bn:'সুবহানা রাব্বিয়াল আ‘লা (৩ বার)',en:'Same as the first sajdah. This completes one rakat.'}];
const QZ=[['You passed urine or stool.',1,'Anything that leaves the private parts breaks wudu.'],['You passed gas.',1,'Wudu breaks. Make it again.'],['You had a wound with blood flowing out.',1,'Flowing blood or pus breaks wudu (Hanafi).'],['You vomited a mouthful.',1,'A mouthful or more breaks wudu.'],['You fell into deep sleep lying down.',1,'Sleeping lying down or leaning breaks wudu.'],['You laughed out loud during a prayer with ruku and sajdah.',1,'It breaks wudu and the prayer (Hanafi).'],['You ate or drank something.',0,'Eating and drinking do not break wudu.'],['You touched your private part.',0,'Does not break wudu in Hanafi fiqh.'],['You are only unsure if your wudu broke.',0,'Doubt does not break it. Keep your wudu.'],['A tiny drop of blood appeared but did not flow.',0,'It must flow to break wudu.'],['You dozed for a moment while sitting upright.',0,'A short nap sitting upright does not break wudu.']];
function guideHTML(){
 const sec=(k,title,sub,body)=>`<section class="gs" id="g-${k}" style="--c:${GC[k]}"><div class="gsh"><span class="ic">${gic(k)}</span><div><h2>${title}</h2><small>${sub}</small></div></div><div class="gsb">${body}</div></section>`;
 const legend=`<div class="gleg"><span class="lg" style="--c:#e2b93b"><i></i>Fard: must do</span><span class="lg" style="--c:#2f8f5b"><i></i>Sunnah or good</span><span class="lg" style="--c:#c0392b"><i></i>Do not</span><span class="lg" style="--c:#2b86c5"><i></i>Tip</span></div>`;
 const nav=`<div class="gnav" id="gnav" role="navigation" aria-label="Guide sections">${GSEC.map(s=>`<a href="#g-${s[0]}" data-s="${s[0]}" style="--c:${GC[s[0]]}"><i></i>${s[1]}</a>`).join('')}</div>`;
 const wudu=sec('wudu','How to make Wudu','Follow the picture: the glowing part is what you wash next',`<div class="stage"><div class="figbox">${wudFig()}</div><div class="stp" id="wstp"></div></div><div class="co must"><b class="k">!</b><div><b>Fard parts (Hanafi):</b> wash the <span class="hl">face</span>, wash both <span class="hl">arms to the elbows</span>, wipe at least <span class="hl">a quarter of the head</span>, wash both <span class="hl">feet to the ankles</span>. The other steps are sunnah.</div></div><div class="co tip"><b class="k">i</b><div>Do not waste water, even at a running tap. Keep the order and do each part fully so no dry spot remains.</div></div>
 <div class="phrase"><span class="ar" lang="ar">أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ</span><span class="bn">আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু</span></div>`);
 const brk=sec('breaks','What breaks Wudu','And what does not: then test yourself',`<div class="brk"><div class="r"><h3>Breaks wudu: make it again</h3><ul class="bl"><li>Anything leaving the private parts: urine, stool, gas.</li><li>Blood or pus that flows out of the body.</li><li>Vomiting a mouthful.</li><li>Sleeping lying down or leaning; fainting; intoxication.</li><li>Laughing out loud in a prayer that has ruku and sajdah.</li></ul></div><div class="g"><h3>Does not break wudu (Hanafi)</h3><ul class="bl ok"><li>Only being unsure: doubt does not break it.</li><li>A tiny drop of blood that does not flow.</li><li>Touching the private part or your spouse.</li><li>Eating or drinking; a short nap sitting upright.</li></ul></div></div><div class="quiz" id="quiz"></div>`);
 const std=sec('stand','Standing (Qiyam)','Face the Qiblah and stand calm and straight',`<div class="stage"><div class="figbox" id="f-stand"></div><div class="stp"><div class="tips3"><div class="tc" style="--c:#2f8f5b"><b>Feet</b>Face the Qiblah, about 4 fingers apart</div><div class="tc" style="--c:#2f8f5b"><b>Eyes</b>Look at the place of sajdah</div><div class="tc" style="--c:#2f8f5b"><b>Boys and men</b>Hands below the navel, right over left</div><div class="tc" style="--c:#2f8f5b"><b>Girls and women</b>Hands on the chest</div></div><div class="co good"><b class="k">✓</b><div>Stand <span class="hl">still and calm</span>. Do not rock or fidget.</div></div></div></div>`);
 const rk=sec('ruku','Ruku (bowing)','Back flat like a table',`<div class="stage"><div class="figbox" id="f-ruku"></div><div class="stp"><ol class="steps"><li><span>Say <b>“Allahu Akbar”</b> and bow.</span></li><li><span>Hands on knees, fingers spread, back flat, head level with the back.</span></li><li><span>Say <b>“Subhana Rabbiyal Azeem”</b> at least 3 times.</span></li><li><span>Rise saying <b>“Sami’Allahu liman hamidah”</b> and <b>“Rabbana lakal hamd”</b>.</span></li></ol><div class="co must"><b class="k">!</b><div>Stop until every bone rests. This calm pause is <span class="hl">tuma’ninah</span> and it is required. Prayer is not complete without it.</div></div></div></div>`);
 const sj=sec('sajdah','Sajdah (prostration)','The closest place to Allah: ask for what you need',`<div class="stage"><div class="figbox" id="f-sajdah"></div><div class="stp"><ol class="steps"><li><span>Say <b>“Allahu Akbar”</b> and go down: knees, hands, then nose and forehead.</span></li><li><span>Fingers together, pointing to the Qiblah, face between the hands.</span></li><li><span>Say <b>“Subhana Rabbiyal A’la”</b> at least 3 times.</span></li><li><span>Sit up, rest calmly, then do the second sajdah.</span></li></ol></div></div><div class="co must"><b class="k">7</b><div>Seven parts touch the ground (the glowing dots): <span class="hl">forehead with nose, both palms, both knees, toes of both feet</span>.</div></div><div class="two2"><div class="co tip" style="margin:0"><b class="k">M</b><div><b>Men:</b> lift the elbows off the ground and keep the tummy away from the thighs.</div></div><div class="co tip" style="margin:0"><b class="k">W</b><div><b>Women:</b> keep the body close and compact, elbows against the sides.</div></div></div>`);
 const body=(w,x1,x2)=>`<svg viewBox="0 0 120 250" aria-hidden="true"><circle class="sh" cx="60" cy="24" r="17"/>${w}</svg>`;
 const dr=sec('dress','Dress code (Awrah)','The teal part must be covered',`<div class="awr"><div><b>Boys and men</b>${body('<path class="sh" d="M32 52Q60 44 88 52L92 118H28Z"/><path class="sh" d="M32 56L14 116M88 56L106 116" fill="none" stroke-width="12" stroke-linecap="round" style="stroke:color-mix(in srgb,#e2b93b 30%,var(--surface))"/><path class="cov" d="M28 100H92L98 176H66L60 150L54 176H22Z"/><path class="sh" d="M28 176H54L52 240H30ZM66 176H92L90 240H68Z"/>')}<p style="margin:6px 0 0;font-weight:700"><span class="hl">Navel to below the knees</span> is the minimum. A cap is recommended.</p></div><div style="--c:#d4568a"><b>Girls and women</b>${body('<path class="cov" d="M30 52Q60 44 90 52L100 240H20Z"/><path class="cov" d="M32 56L12 130M88 56L108 130" fill="none" stroke-width="13" stroke-linecap="round"/><circle class="sh" cx="14" cy="136" r="8"/><circle class="sh" cx="106" cy="136" r="8"/><path class="cov" d="M42 8Q60-8 78 8V30Q60 44 42 30Z" style="opacity:.9"/><circle class="sh" cx="60" cy="26" r="11"/>')}<p style="margin:6px 0 0;font-weight:700">Cover the <span class="hl">whole body except face, hands and feet</span>. Clothes not see-through or tight.</p></div></div><div class="co good"><b class="k">✓</b><div>Clothes, body and prayer place must be <b>clean (pak)</b>. Use a clean mat or floor and face the Qiblah.</div></div>`);
 const CH=['My body is clean and I have wudu','My clothes and prayer place are clean','My awrah is covered','I am facing the Qiblah','The prayer time has come in','I made my niyyah'];
 const es=sec('ess','Essentials of Salah','Tick what you have done before you say the first Takbir',`<div class="prog2"><i id="chp"></i></div><ul class="chk" id="chk">${CH.map((c,i)=>`<li><label><input type="checkbox" data-i="${i}"><span>${c}</span></label></li>`).join('')}</ul><div class="two2"><div><h3>Before the prayer <span class="tag2 fardt">Conditions</span></h3><ul class="bul"><li>Body clean from hadath (wudu or ghusl).</li><li>Body, clothes and place clean.</li><li>Awrah covered, Qiblah faced.</li><li>Prayer time has begun, niyyah made.</li></ul></div><div><h3>Inside the prayer <span class="tag2 fardt">Fard</span></h3><ul class="bul"><li><b>Takbir Tahrimah</b> to begin.</li><li><b>Qiyam</b>: standing (in fard).</li><li><b>Qira’ah</b>: at least one verse.</li><li><b>Ruku</b> and two <b>Sajdahs</b> in every rakat.</li><li><b>Final sitting</b> long enough for Tashahhud.</li></ul></div></div><div class="co tip"><b class="k">i</b><div>Wajib parts like Al-Fatiha and a surah must not be left. If forgotten by mistake, <b>Sajdah Sahw</b> fixes it. Ask your teacher.</div></div>`);
 const DN=['Talking, eating or drinking','Laughing, or turning the chest from the Qiblah','Looking around or up at the sky','Playing with clothes, hair or fingers','Big unnecessary movements','Rushing without tuma’ninah','Praying when you badly need the toilet','Praying at sunrise, midday (zawal) and sunset','Walking in front of someone praying'];
 const dn=sec('donts','What not to do in Salah','Each of these harms your prayer or its reward',`<div class="dn">${DN.map((d,i)=>`<div style="animation-delay:${i*80}ms">${d}</div>`).join('')}</div>`);
 const kh=sec('khushu','Khushu: how to get the highest reward','Calm heart, present mind',`<div class="quote">“Worship Allah as if you see Him. If you do not see Him, He sees you.”<small>Bukhari, Muslim</small></div><div class="kh"><div><h3><span class="twk">★</span> Pray on time</h3><p>And in jamaah at the masjid when you can.</p></div><div><h3><span class="twk">★</span> Know the meaning</h3><p>Learn Al-Fatiha and the short surahs by heart.</p></div><div><h3><span class="twk">★</span> Eyes on sajdah</h3><p>Look at the place of sajdah and stay calm in every position.</p></div><div><h3><span class="twk">★</span> Recite slowly</h3><p>Do not rush. Give each part its right.</p></div><div><h3><span class="twk">★</span> Ask in sajdah</h3><p>Make dua for what you need.</p></div><div><h3><span class="twk">★</span> Sunnah and dhikr</h3><p>Pray the sunnah and finish with dhikr.</p></div></div><p style="margin-top:16px"><a class="btn" href="#/dua/after">Dhikr after every Salah →</a> <a class="btn ghost" href="#/surah/every">Tashahhud, Durood & Dua →</a></p>`);
 const player=`<div class="gs" id="g-player" style="--c:#7a4fb5;margin-top:26px"><div class="gsh"><span class="ic">${gic('stand')}</span><div><h2>Watch one full rakat</h2><small>Press play and follow the postures and words</small></div></div><div class="gsb"><div class="stage"><div class="figbox" id="f-play"></div><div class="stp" id="pstp"></div></div></div></div>`;
 return `<div class="gd">${legend}${nav}${wudu}${brk}${player}${std}${rk}${sj}${dr}${es}${dn}${kh}</div>`}
function guideInit(){
 const hh=document.querySelector('header').offsetHeight;document.querySelector('.gd').style.setProperty('--hh',(matchMedia('(max-width:720px)').matches?hh:hh)+'px');
 // wudu stepper
 let wi=0,wt=null;const wst=$('#wstp'),wf=app.querySelector('.figbox');
 function wr(){const s=WSTEPS[wi];app.querySelectorAll('.zone').forEach(z=>z.classList.toggle('on',z.classList.contains('z-'+s.z)));
  wst.innerHTML=`<div class="pills"><span class="tag2">Step ${wi+1} of ${WSTEPS.length}</span>${s.f?'<span class="tag2 fardt">Fard</span>':''}</div><h3>${s.t}</h3><p class="n" style="margin:0">${s.n}</p>${s.c?`<div class="pills"><div class="dots go">${'<b></b>'.repeat(s.c)}</div><b>× ${s.c}</b></div>`:''}<div class="ctrl"><button class="cb" id="wp">← Back</button><button class="cb pri" id="wpl">${wt?'❚❚ Pause':'▶ Play'}</button><button class="cb" id="wn">Next →</button></div><div class="prog">${WSTEPS.map((x,i)=>`<button data-i="${i}" class="${i===wi?'on':i<wi?'done':''}" aria-label="Step ${i+1}">${i+1}</button>`).join('')}</div>`;
  $('#wp').onclick=()=>{stop();wi=(wi+9)%10;wr()};$('#wn').onclick=()=>{stop();wi=(wi+1)%10;wr()};$('#wpl').onclick=()=>{wt?stop(true):play()};
  wst.querySelectorAll('.prog button').forEach(b=>b.onclick=()=>{stop();wi=+b.dataset.i;wr()})}
 function stop(r){clearInterval(wt);wt=null;if(r)wr()}
 function play(){wt=setInterval(()=>{wi=(wi+1)%10;wr()},3800);wr()}
 wr();
 // quiz
 let qi=0,sc=0,ans=false;const qz=$('#quiz');
 function qr(){if(qi>=QZ.length){qz.innerHTML=`<h3>Well done!</h3><p class="q">You got ${sc} of ${QZ.length} right.</p><button class="cb pri" style="--c:#2b86c5" id="qa">Try again</button>`;$('#qa').onclick=()=>{qi=0;sc=0;qr()};return}
  const it=QZ[qi];qz.innerHTML=`<span class="eyebrow">Does it break wudu? ${qi+1} of ${QZ.length}</span><div class="qbar"><i style="width:${qi/QZ.length*100}%"></i></div><div class="q">${it[0]}</div><div class="yn"><button class="b1" data-a="1">Breaks it</button><button class="b2" data-a="0">Does not break it</button></div><div id="qf"></div>`;ans=false;
  qz.querySelectorAll('.yn button').forEach(b=>b.onclick=()=>{if(ans)return;ans=true;const ok=(+b.dataset.a)===it[1];if(ok)sc++;$('#qf').innerHTML=`<div class="fb ${ok?'y':'n'}">${ok?'Correct! ':'Not quite. '}${it[2]}</div><p style="margin:10px 0 0"><button class="cb pri" style="--c:#2b86c5" id="qn">${qi+1===QZ.length?'See score':'Next →'}</button></p>`;$('#qn').onclick=()=>{qi++;qr()}})}
 qr();
 // static poses
 mkFig($('#f-stand'),'qiyam');mkFig($('#f-ruku'),'ruku');mkFig($('#f-sajdah'),'sajdah',true).set('sajdah',true);
 // player
 const pf=mkFig($('#f-play'),'qiyam');let pi=0,pt=null;const ps=$('#pstp');
 function pr(){const s=PSEQ[pi];pf.set(s.p);ps.innerHTML=`<h3>${s.t}</h3><div class="phrase"><span class="ar" lang="ar">${s.ar}</span><span class="bn">${s.bn}</span></div><p class="n" style="margin:0">${s.en}</p><div class="ctrl"><button class="cb" id="pp">← Back</button><button class="cb pri" id="ppl">${pt?'❚❚ Pause':'▶ Play'}</button><button class="cb" id="pn">Next →</button></div><div class="prog">${PSEQ.map((x,i)=>`<button data-i="${i}" class="${i===pi?'on':i<pi?'done':''}" aria-label="${x.t}">${i+1}</button>`).join('')}</div>`;
  $('#pp').onclick=()=>{pst();pi=(pi+5)%6;pr()};$('#pn').onclick=()=>{pst();pi=(pi+1)%6;pr()};$('#ppl').onclick=()=>{if(pt)pst(true);else{pt=setInterval(()=>{pi=(pi+1)%6;pr()},3800);pr()}};ps.querySelectorAll('.prog button').forEach(b=>b.onclick=()=>{pst();pi=+b.dataset.i;pr()})}
 function pst(r){clearInterval(pt);pt=null;if(r)pr()}
 pr();
 // checklist
 const cks=[...document.querySelectorAll('#chk input')];cks.forEach(c=>c.onchange=()=>{$('#chp').style.width=cks.filter(x=>x.checked).length/cks.length*100+'%'});
 // scrollspy
 const links=[...document.querySelectorAll('#gnav a')];
 const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){links.forEach(l=>l.classList.toggle('on',l.dataset.s===e.target.id.slice(2)));const a=document.querySelector('#gnav a.on');if(a)a.scrollIntoView({inline:'center',block:'nearest'})}})},{rootMargin:'-30% 0px -60% 0px'});
 GSEC.forEach(s=>{const el=document.getElementById('g-'+s[0]);el&&io.observe(el)});
 links.forEach(l=>l.onclick=e=>{e.preventDefault();document.getElementById('g-'+l.dataset.s).scrollIntoView({behavior:'smooth'})})}

const SITE='Kids Daily Islamic Lessons',DESC0='Free lessons for children and families: surahs for salah with Bangla pronunciation, how to pray the five daily prayers, wudu guide, Arabic alphabet writing practice, dhikr and duas.';
function segs(){const s=PROD?location.pathname.replace(/^\/+|\/+$/g,''):location.hash.replace(/^#\/?/,'');return s.split('/').filter(Boolean).slice(0,4)}
function go(p){if(PROD){history.pushState({},'',p);setTimeout(route,0)}else location.hash='#'+p}
function fixLinks(){if(!PROD)return;document.querySelectorAll('a[href^="#/"]').forEach(a=>a.setAttribute('href',a.getAttribute('href').slice(1)))}
function setMeta(sel,attr,val,create){let e=document.querySelector(sel);if(!e){if(!create)return;e=document.createElement(create.t);for(const k in create.a)e.setAttribute(k,create.a[k]);document.head.appendChild(e)}e.setAttribute(attr,val)}
function applyMeta(title,desc,path,noindex){
 const full=title===SITE?SITE+' | Surahs, Salah, Arabic Alphabet & Duas':title+' | '+SITE;document.title=full;
 if(!PROD)return;const base=(KDIL.SITE_URL||location.origin).replace(/\/$/,''),url=base+(path==='/'?'/':path);
 setMeta('meta[name=description]','content',desc,{t:'meta',a:{name:'description'}});
 setMeta('link[rel=canonical]','href',url,{t:'link',a:{rel:'canonical'}});
 setMeta('meta[name=robots]','content',noindex?'noindex,follow':'index,follow',{t:'meta',a:{name:'robots'}});
 [['og:title',full],['og:description',desc],['og:url',url],['og:type','website'],['og:site_name',SITE],['og:image',base+'/og-image.png']].forEach(([p,v])=>setMeta('meta[property="'+p+'"]','content',v,{t:'meta',a:{property:p}}));
 [['twitter:card','summary_large_image'],['twitter:title',full],['twitter:description',desc],['twitter:image',base+'/og-image.png']].forEach(([n,v])=>setMeta('meta[name="'+n+'"]','content',v,{t:'meta',a:{name:n}}))}
function notFound(){setNav('');app.innerHTML=`<section class="hero"><h1>Page not found</h1><p class="lead">This page does not exist. Let us go back to the lessons.</p><a class="btn" href="#/">Go home</a></section>`}
function route(){
 const s=segs(),a=s[0]||'',b=s[1],c=s[2];let T=SITE,De=DESC0,P='/'+s.join('/'),NI=false;
 if(a==='surah'){
  if(b==='every'){everyView();T='Surahs to read in every Salah';De='Tashahhud, Durood and Dua read in every prayer, with Arabic, Bangla pronunciation and meaning.'}
  else if(b){if(!/^\d{1,3}$/.test(b)){notFound();NI=true;T='Not found'}else{reader(+b);const x=D.sur.find(q=>q.n==+b);if(x&&x.s){T='Surah '+x.t+' with Bangla pronunciation';De='Read Surah '+x.t+' ('+x.tr+') for salah: Arabic text, Bangla pronunciation and meaning in Bangla and English.'}else NI=true}}
  else{surahList();T='Surah for Salah';De='All 114 surahs, and the short surahs used in salah with Arabic, Bangla pronunciation and translation.'}}
 else if(a==='salah'){
  if((b==='fard'||b==='extra')&&c){prayer(b,c);const L=b==='fard'?D.fard:D.extra,p=L.find(x=>x.key===c);if(p){T='How to pray '+p.en;De='Step by step how to pray '+p.en+': rakats, niyyah, what to recite, for children and families.'}else NI=true}
  else if(b==='guide'){salahHome('guide');T='Wudu and Salah guide';De='How to make wudu, how to stand, bow and prostrate, dress code, what breaks wudu, what to avoid and how to gain khushu.';P='/salah/guide'}
  else if(b==='extra'){salahHome('extra');T='Extra Prayers: Sunnah, Wajib and Nafl';De='Tahajjud, Duha, Awwabin, Witr and other extra prayers explained simply.'}
  else{salahHome('fard');T='The 5 Daily Fard Prayers';De='Fajr, Zuhr, Asr, Maghrib and Isha: rakats and how to pray each one.';P='/salah/fard'}}
 else if(a==='alphabet'){alphabet();T='Arabic Alphabet for Kids';De='All 28 Arabic letters with Bangla sounds, jabar, jer and pesh, plus a free printable writing practice PDF.'}
 else if(a==='dua'){duaView(b==='dua'?'dua':'after');T=b==='dua'?'Duas for family, health and rizq':'Dhikr after every Salah';De=b==='dua'?'Duas for parents, family, children, health, rizq and those who passed away.':'Tasbih and dhikr to read after every prayer, with Arabic and Bangla.';P=b==='dua'?'/dua/dua':'/dua/after'}
 else if(a==='feedback'){feedback();T='Feedback';De='Share your opinion, an idea or a correction with us.'}
 else if(a==='privacy'){privacy();T='Privacy and Cookies';De='How we handle feedback messages, analytics and cookies.'}
 else if(a===''){home();P='/'}
 else{notFound();NI=true;T='Page not found'}
 fixLinks();window.scrollTo(0,0);applyMeta(T,De,P,NI);trackPage(P,document.title)}
if(PROD){addEventListener('popstate',route);document.addEventListener('click',e=>{if(e.defaultPrevented||e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest&&e.target.closest('a[href^="/"]');if(!a||a.target||a.hasAttribute('download')||/^\/(downloads|api)\//.test(a.getAttribute('href')))return;e.preventDefault();history.pushState({},'',a.getAttribute('href'));route()})}
else addEventListener('hashchange',route);

/* ---------- consent + analytics ---------- */
const CK='kdil_ck';let consent=store.get(CK,null);
function track(name,params){try{if(consent&&consent.a&&window.gtag)gtag('event',name,params||{})}catch(e){}}
function trackPage(p,title){track('page_view',{page_path:p,page_title:title,page_location:location.origin+p})}
function loadGA(){if(!PROD||!KDIL.GA_ID||window.__ga)return;window.__ga=1;window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};
 gtag('consent','default',{analytics_storage:'denied',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});gtag('js',new Date());
 gtag('config',KDIL.GA_ID,{send_page_view:false,anonymize_ip:true,allow_google_signals:false,allow_ad_personalization_signals:false});
 const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(KDIL.GA_ID);document.head.appendChild(s)}
function clearGA(){try{document.cookie.split(';').forEach(c=>{const n=c.split('=')[0].trim();if(/^_ga/.test(n)){const h=location.hostname.split('.');for(let i=0;i<h.length-1;i++){const d='.'+h.slice(i).join('.');document.cookie=n+'=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/;domain='+d}document.cookie=n+'=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'}})}catch(e){}}
function setConsent(a){consent={a:!!a,t:Date.now()};store.set(CK,consent);
 if(a){loadGA();if(window.gtag){gtag('consent','update',{analytics_storage:'granted'});if(KDIL.GA_ID)window['ga-disable-'+KDIL.GA_ID]=false;trackPage('/'+segs().join('/'),document.title)}}
 else{if(window.gtag)gtag('consent','update',{analytics_storage:'denied'});if(KDIL.GA_ID)window['ga-disable-'+KDIL.GA_ID]=true;clearGA()}
 const b=$('#ckb');if(b)b.remove()}
function ckBanner(){if(consent||$('#ckb'))return;const d=document.createElement('div');d.id='ckb';d.className='ckb';d.setAttribute('role','region');d.setAttribute('aria-label','Cookie notice');
 d.innerHTML=`<p><b>Cookies.</b> We use only privacy-friendly analytics, and only if you agree, to see how many people use the site and which lessons help most. No ads, no selling of data. <a href="#/privacy">Learn more</a></p><div class="row"><button class="btn" id="ck1" type="button">Accept analytics</button><button class="btn ghost" id="ck0" type="button">Necessary only</button><button class="btn ghost" id="ck2" type="button">Settings</button></div>`;
 document.body.appendChild(d);fixLinks();$('#ck1').onclick=()=>setConsent(true);$('#ck0').onclick=()=>setConsent(false);$('#ck2').onclick=ckDialog}
function ckDialog(){let d=$('#ckd');if(d)d.remove();d=document.createElement('dialog');d.id='ckd';d.className='ckd';d.setAttribute('aria-labelledby','ckdt');
 d.innerHTML=`<h2 id="ckdt" style="margin-top:0">Cookie settings</h2><div class="opt"><div><b>Necessary</b><p>Remembers your choices on this device (theme, text size, learned surahs, this cookie choice). Always on.</p></div><input type="checkbox" checked disabled aria-label="Necessary, always on"></div><div class="opt"><div><b>Analytics</b><p>Anonymous visit statistics (Google Analytics): how many visitors, which pages, how long, and where they came from. Off unless you turn it on.</p></div><input type="checkbox" id="cka" aria-label="Analytics"${consent&&consent.a?' checked':''}></div><p style="color:var(--muted);font-size:.9rem">There are no advertising cookies on this site.</p><div class="row" style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="cks" type="button">Save choice</button><button class="btn ghost" id="ckc" type="button">Close</button></div>`;
 document.body.appendChild(d);const close=()=>{d.close();d.remove()};
 $('#cks').onclick=()=>{setConsent($('#cka').checked);close();toast('Cookie choice saved')};$('#ckc').onclick=close;d.addEventListener('cancel',()=>d.remove());
 if(d.showModal)d.showModal();else d.setAttribute('open','')}
$('#ckset').onclick=ckDialog;
if(!PROD)$('#pvnote').textContent='Preview: the feedback form, analytics and search settings become live when the site is deployed.';
if(consent&&consent.a)loadGA();
ckBanner();

/* ---------- feedback ---------- */
let lastSend=0;
function feedback(){setNav('feedback');const t0=Date.now();
 app.innerHTML=`<span class="eyebrow">We would love to hear from you</span><h1>Feedback</h1><p class="lead">Share your opinion, an idea, a correction or a dua for us. Tell us who you are first, then write your message.</p>
 <form class="fbf" id="fbf" novalidate autocomplete="on"><div class="two2"><label>Your name<input id="fn" name="name" maxlength="80" autocomplete="name" required></label><label>Your email<small>Only used to reply. Never shown or shared.</small><input id="fe" name="email" type="email" maxlength="120" autocomplete="email" inputmode="email" required></label></div>
 <label>Topic<select id="ft"><option>Opinion</option><option>Idea or suggestion</option><option>Correction (mistake in a lesson)</option><option>Praise or dua</option><option>Other</option></select></label>
 <label>Your message<small id="fh2">Please enter your name and email above to unlock this box.</small><textarea id="fm" maxlength="2000" disabled placeholder="Write your message here (10 to 2000 characters)"></textarea></label><div class="cn" id="fc">0 / 2000</div>
 <div class="hp" aria-hidden="true"><label>Website<input id="fw" name="website" tabindex="-1" autocomplete="off"></label></div>
 <label class="chk"><input type="checkbox" id="fk"><span>I agree that my name, email and message are sent to the site owner so he can read and reply. <a href="#/privacy">Privacy</a></span></label>
 <div class="err" id="fe2" role="alert" aria-live="polite"></div><button class="btn" id="fs" type="submit">Send feedback</button></form>`;
 fixLinks();
 const fn=$('#fn'),fe=$('#fe'),fm=$('#fm'),EM=/^[^\s@<>()"',;:]+@[^\s@<>()"',;:]+\.[^\s@<>()"',;:]{2,}$/;
 const ok0=()=>fn.value.trim().length>=2&&EM.test(fe.value.trim());
 const unlock=()=>{const o=ok0();fm.disabled=!o;$('#fh2').textContent=o?'Thank you. Now write your message.':'Please enter your name and email above to unlock this box.'};
 fn.oninput=fe.oninput=unlock;fm.oninput=()=>{$('#fc').textContent=fm.value.length+' / 2000'};
 $('#fbf').onsubmit=async ev=>{ev.preventDefault();const er=$('#fe2');er.textContent='';
  const name=fn.value.trim(),email=fe.value.trim(),msg=fm.value.trim();
  if(name.length<2){er.textContent='Please enter your name.';fn.focus();return}
  if(!EM.test(email)){er.textContent='Please enter a valid email address.';fe.focus();return}
  if(msg.length<10){er.textContent='Please write at least 10 characters.';fm.focus();return}
  if(!$('#fk').checked){er.textContent='Please tick the box to agree.';return}
  if(Date.now()-lastSend<30000){er.textContent='Please wait a little before sending another message.';return}
  const btn=$('#fs');btn.disabled=true;btn.textContent='Sending…';
  const done=demo=>{lastSend=Date.now();app.innerHTML=`<div class="fbdone"><div style="font-size:2.4rem" aria-hidden="true">✅</div><h2>JazakAllahu khayran, ${esc(name)}!</h2><p>${demo?'Preview mode: nothing was sent. Once the site is deployed, your message will reach the owner.':'Your message has been sent. If you asked for a reply, we will write back to your email.'}</p><a class="btn" href="#/">Back to lessons</a></div>`;fixLinks()};
  if(!PROD){setTimeout(()=>done(true),500);return}
  try{const r=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,type:$('#ft').value,message:msg,website:$('#fw').value,elapsed:Date.now()-t0})});
   if(r.ok){track('feedback_sent');done(false)}else{const j=await r.json().catch(()=>({}));er.textContent=j.error||'Could not send. Please try again later.';btn.disabled=false;btn.textContent='Send feedback'}}
  catch(e){er.textContent='Network problem. Please try again.';btn.disabled=false;btn.textContent='Send feedback'}}}

/* ---------- privacy ---------- */
function privacy(){setNav('');app.innerHTML=`<span class="eyebrow">Your trust matters</span><h1>Privacy &amp; Cookies</h1><div class="prv">
<p class="lead">Short version: no ads, no selling data, and analytics only if you say yes.</p>
<h2>Feedback messages</h2><p>If you send feedback we receive your name, email, topic and message. We use them only to read your message and reply. Your email is never shown on the site and never shared. Messages are delivered by email through a mail-sending service.</p>
<h2>Analytics (only with your consent)</h2><p>If you choose “Accept analytics”, we use Google Analytics to count visitors, see which pages are opened, how long people stay and which website or search brought them here. IP addresses are anonymised and advertising features are off. You can change or withdraw your choice anytime with “Cookie settings” in the footer.</p>
<h2>Stored on your device</h2><p>The site saves small settings in your browser (theme, text size, surahs you marked as learned, your cookie choice). They never leave your device.</p>
<h2>Third parties</h2><p>Fonts are loaded from Google Fonts. Google Analytics loads only after you agree.</p>
<h2>Advertising</h2><p>This site has no advertising and does not use advertising cookies.</p>
<h2>Children</h2><p>The lessons are for children, but the feedback form is meant for parents, teachers and adults. Children should ask a parent before sending a message.</p>
<h2>Contact</h2><p>Use the <a href="#/feedback">feedback form</a>. This page is a plain-language summary, not legal advice.</p></div>`}

route();
